<!doctype html>
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>登录设备</title><link rel="stylesheet" href="/assets/css/style.css"><style>.devices-page{min-height:100vh;padding:18px 16px 110px;background:var(--bg-main,#f6f8fb)}.devices-shell{max-width:860px;margin:0 auto}.devices-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}.devices-title{font-size:24px;font-weight:950;color:var(--text-main,#0f172a)}.devices-sub{font-size:13px;color:var(--text-soft,#64748b);margin-top:4px}.device-list{display:grid;gap:10px}.device-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:14px 16px;border:1px solid var(--line-soft,#e2e8f0);border-radius:18px;background:var(--card-bg,#fff);box-shadow:0 8px 24px rgba(15,23,42,.04)}.device-name{font-weight:950;color:var(--text-main,#0f172a)}.device-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px;color:var(--text-soft,#64748b);font-size:12px}.device-pill{height:22px;display:inline-flex;align-items:center;border-radius:999px;background:var(--input-bg,#f8fafc);border:1px solid var(--line-soft,#e2e8f0);padding:0 8px;font-weight:800}.device-current{color:#0284c7;background:#e0f2fe;border-color:#bae6fd}.device-revoked{color:#94a3b8}.device-row .btn{height:30px!important;padding:0 10px!important;border-radius:999px!important;font-size:12px!important}.alert{padding:10px 12px;border-radius:14px;margin-bottom:12px;font-size:13px;background:#dcfce7;color:#15803d}@media(max-width:640px){.devices-page{padding:14px 12px 104px}.devices-head,.device-row{display:grid;align-items:start}.devices-title{font-size:22px}}</style></head><body><?php require __DIR__ . '/../layouts/topbar.php'; ?><main class="devices-page"><div class="devices-shell"><div class="devices-head"><div><div class="devices-title">登录设备</div><div class="devices-sub">查看登录过的设备与 IP，可退出其他设备。</div></div><a class="btn btn-light" style="text-decoration:none;" href="/index.php?path=settings">返回设置</a></div><?php if($success): ?><div class="alert"><?= htmlspecialchars($success) ?></div><?php endif; ?><div class="device-list"><?php foreach($devices as $device): ?><?php $revoked=!empty($device['revoked_at']); ?><div class="device-row <?= $revoked?'device-revoked':'' ?>"><div><div class="device-name"><?= htmlspecialchars((string)$device['device_name']) ?> <?php if(!empty($device['is_current'])): ?><span class="device-pill device-current">当前设备</span><?php endif; ?> <?php if($revoked): ?><span class="device-pill">已退出</span><?php endif; ?></div><div class="device-meta"><span class="device-pill">IP <?= htmlspecialchars((string)($device['ip_address'] ?: '未知')) ?></span><span class="device-pill">登录 <?= htmlspecialchars((string)$device['login_at']) ?></span><span class="device-pill">活跃 <?= htmlspecialchars((string)$device['last_active_at']) ?></span></div></div><div><?php if(!$revoked && empty($device['is_current'])): ?><form method="post" onsubmit="return confirm('确认让该设备退出登录？')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$device['id'] ?>"><button class="btn btn-light" type="submit">退出登录</button></form><?php elseif(!empty($device['is_current'])): ?><a class="btn btn-light" style="text-decoration:none;" href="/index.php?path=logout">退出当前设备</a><?php else: ?><span class="devices-sub">已失效</span><?php endif; ?></div></div><?php endforeach; ?><?php if(empty($devices)): ?><div class="device-row"><div class="devices-sub">暂无登录设备记录。</div></div><?php endif; ?></div></div></main><?php require dirname(__DIR__, 2) . '/layouts/theme-toggle.php'; ?><?php require __DIR__ . '/../layouts/bottom-nav.php'; ?></body></html>
